import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int m = nextInt();
        boolean hasBest = false, hasAnswer = false;
        long best = 0, answer = 0;
        for (int j = 0; j < m; j++) {
            long value = nextLong();
            // Departures strictly before j: add departure j-1 if it exists.
            if (j - 1 >= 0 && j - 1 < n) {
                best = hasBest ? Math.min(best, a[j - 1]) : a[j - 1];
                hasBest = true;
            }
            if (hasBest) {
                answer = hasAnswer ? Math.min(answer, best + value) : best + value;
                hasAnswer = true;
            }
        }
        System.out.println(hasAnswer ? answer : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	m := int(nextInt())
	hasBest, hasAnswer := false, false
	var best, answer int64
	for j := 0; j < m; j++ {
		value := nextInt()
		// Departures strictly before j: add departure j-1 if it exists.
		if j-1 >= 0 && j-1 < n {
			if !hasBest || a[j-1] < best {
				best = a[j-1]
			}
			hasBest = true
		}
		if hasBest {
			if !hasAnswer || best+value < answer {
				answer = best + value
			}
			hasAnswer = true
		}
	}
	if !hasAnswer {
		answer = -1
	}
	fmt.Println(answer)
}
